import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const OrdersDisplay = () => {
    const navigate = useNavigate();
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [confirmDelete, setConfirmDelete] = useState(null);

    // Fetch orders from backend
    const fetchOrders = async () => {
        try {
            const response = await axios.get('http://localhost:5000/orders');
            setOrders(response.data.orders || []);
            setLoading(false);
        } catch (err) {
            setError('Failed to fetch orders');
            setLoading(false);
        }
    };

    // Delete order functionality
    const handleDeleteOrder = async (orderId) => {
        try {
            await axios.delete(`http://localhost:5000/orders/${orderId}`);
            // Refresh orders after deletion
            fetchOrders();
            setConfirmDelete(null);
        } catch (err) {
            alert('Failed to delete order');
        }
    };

    // View/Edit order functionality
    const handleEditOrder = (orderId) => {
        navigate(`/update-order/${orderId}`);
    };

    // Trigger initial fetch
    useEffect(() => {
        fetchOrders();
    }, []);

    // Render loading state
    if (loading) {
        return (
            <div className="flex justify-center items-center h-screen">
                <div className="animate-spin rounded-full h-32 w-32 border-t-2 border-blue-500"></div>
            </div>
        );
    }

    // Render error state
    if (error) {
        return <div className="text-red-500 text-center mt-10">{error}</div>;
    }

    return (
        <div className="container mx-auto p-4">
            <h1 className="text-3xl font-bold mb-6 text-center">Orders Management</h1>
            
            {orders.length === 0 ? (
                <p className="text-center text-gray-600">No orders found.</p>
            ) : (
                <div className="overflow-x-auto shadow-md rounded-lg">
                    <table className="w-full">
                        <thead className="bg-gray-100 border-b">
                            <tr>
                                <th className="p-3 text-left">Order ID</th>
                                <th className="p-3 text-left">Name</th>
                                <th className="p-3 text-left">Email</th>
                                <th className="p-3 text-left">Phone</th>
                                <th className="p-3 text-left">Pickup Time</th>
                                <th className="p-3 text-left">Status</th>
                                <th className="p-3 text-center">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {orders.map((order) => (
                                <tr 
                                    key={order._id} 
                                    className="border-b hover:bg-gray-50 transition-colors"
                                >
                                    <td className="p-3">{order.orderId}</td>
                                    <td className="p-3">{order.firstName} {order.lastName}</td>
                                    <td className="p-3">{order.email}</td>
                                    <td className="p-3">{order.phoneNumber}</td>
                                    <td className="p-3">{order.pickupTime}</td>
                                    <td className="p-3">
                                        <span 
                                            className={`px-2 py-1 rounded text-xs font-semibold ${
                                                order.orderStatus === 'Completed' 
                                                    ? 'bg-green-100 text-green-800' 
                                                    : order.orderStatus === 'Pending' 
                                                    ? 'bg-yellow-100 text-yellow-800' 
                                                    : 'bg-gray-100 text-gray-800'
                                            }`}
                                        >
                                            {order.orderStatus}
                                        </span>
                                    </td>
                                    <td className="p-3">
                                        <div className="flex justify-center space-x-2">
                                            {/* View/Edit Button */}
                                            <button 
                                                onClick={() => handleEditOrder(order._id)}
                                                className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600 transition"
                                            >
                                                View/Edit
                                            </button>
                                            
                                            {/* Delete Button */}
                                            <button 
                                                onClick={() => setConfirmDelete(order._id)}
                                                className="bg-red-500 text-white px-3 py-1 rounded hover:bg-red-600 transition"
                                            >
                                                Delete
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Confirmation Dialog */}
            {confirmDelete && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center">
                    <div className="bg-white p-6 rounded-lg shadow-xl">
                        <h2 className="text-xl font-bold mb-4">Confirm Deletion</h2>
                        <p className="mb-4">Are you sure you want to delete this order?</p>
                        <div className="flex justify-end space-x-3">
                            <button 
                                onClick={() => setConfirmDelete(null)}
                                className="bg-gray-200 text-gray-800 px-4 py-2 rounded hover:bg-gray-300"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={() => handleDeleteOrder(confirmDelete)}
                                className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600"
                            >
                                Delete
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default OrdersDisplay;
